/*
 * Transcoding tests for the samr coders: the request and reply of every
 * operation, and LookupDomainInSamServer for the account domain, Builtin
 * and a domain that does not exist. See coder-test.h for the tests run
 * per case.
 *
 * Where the known-good NDR stubs come from (win16-1, Windows Server 2016):
 *
 * - Replies were captured from the server. Windows always replies in its
 *   native format, so there are only NDR32 and NDR64 little-endian ones.
 * - Requests were encoded by libdcerpc and sent to the server, which
 *   accepted them as NDR32 LE, NDR32 BE and NDR64 LE and answered each
 *   flavor alike apart from the context handles. Windows does not support
 *   NDR64 BE.
 * - The calls ran as one chain per flavor: Connect,
 *   EnumerateDomainsInSamServer, LookupDomainInSamServer for
 *   WIN-OR90BFOC38G, Builtin and NoSuchDomain (STATUS_NO_SUCH_DOMAIN, no
 *   DomainId), CloseHandle, Connect2 and CloseHandle, Connect5 and
 *   CloseHandle.
 * - The user calls ran as a second chain per flavor: Connect5,
 *   OpenDomain for the account domain, LookupNamesInDomain for
 *   Administrator, Guest and UserDoesNotExist (STATUS_SOME_NOT_MAPPED),
 *   OpenUser for Administrator (500), QueryInformationUser for every
 *   class a client can query, GetGroupsForUser, QuerySecurityObject on
 *   the user, then OpenDomain for Builtin and GetAliasMembership for
 *   Administrator and None (513). Of the QueryInformationUser requests,
 *   which only differ in the class, UserAllInformation is here.
 * - The account calls ran on ad-adc (Windows Server 2016, a domain
 *   controller) as a third chain per flavor: Connect2, OpenDomain,
 *   CreateUser2InDomain for a workstation account, SetInformationUser2
 *   with its password (UserInternal5Information in one account,
 *   UserInternal5InformationNew in another) and then
 *   UserControlInformation to enable it, and OpenUser and DeleteUser.
 *   The password buffers are encrypted with the SMB application key, so
 *   they differ in every capture; each password was checked with a
 *   netlogon ServerAuthenticate3 for the account.
 *
 * The data was generated from the captures; cases whose captures differ
 * in live values are split into one case per capture.
 *
 * Strings are char *, so a re-encoded RPC_UNICODE_STRING has the
 * MaximumLength libdcerpc gives it, and an empty one a NULL Buffer.
 * Windows sends MaximumLength equal to Length and empty strings with a
 * Buffer, so the user information replies that hold such strings do not
 * re-encode to the captured NDR (XFAIL).
 */

#include <stdint.h>
#include <stddef.h>

#include <dcerpc/dcerpc.h>
#include <dcerpc/samr.h>

#include "coder-test.h"

